package dev.mineagent.runtime.neoforge.command;
import net.minecraft.commands.Commands;import com.mojang.brigadier.arguments.StringArgumentType;import dev.mineagent.runtime.neoforge.ui.ServerChatSettings;
public final class ChatPreferenceCommands {
 public static void register(com.mojang.brigadier.CommandDispatcher<net.minecraft.commands.CommandSourceStack> d){var deep=Commands.literal("deep").executes(c->ServerChatSettings.menu(c.getSource().getPlayerOrException(),"deep"));for(String level:java.util.List.of("off","low","medium","high","max"))deep.then(Commands.literal(level).executes(c->ServerChatSettings.depth(c.getSource().getPlayerOrException(),level,"")).then(Commands.argument("agent",StringArgumentType.greedyString()).executes(c->ServerChatSettings.depth(c.getSource().getPlayerOrException(),level,StringArgumentType.getString(c,"agent")))));var see=Commands.literal("see").executes(c->{ServerChatSettings.sendDisplay(c.getSource().getPlayerOrException(),"toggle");return 1;});for(String value:java.util.List.of("on","off"))see.then(Commands.literal(value).executes(c->{ServerChatSettings.sendDisplay(c.getSource().getPlayerOrException(),value);return 1;}));d.register(Commands.literal("ai").then(Commands.literal("access_reply").then(Commands.argument("pending",net.minecraft.commands.arguments.UuidArgument.uuid()).then(Commands.argument("choice",StringArgumentType.word()).executes(c->{try{return dev.mineagent.runtime.neoforge.ui.ServerChatAccess.decide(c.getSource().getPlayerOrException(),net.minecraft.commands.arguments.UuidArgument.getUuid(c,"pending"),StringArgumentType.getString(c,"choice"));}catch(Exception e){c.getSource().sendFailure(net.minecraft.network.chat.Component.literal("响应许可未生效："+e.getMessage()));return 0;}})))).then(Commands.literal("chat").then(Commands.literal("delete").executes(c->{try{return dev.mineagent.runtime.neoforge.ui.ServerConversations.get(c.getSource().getServer()).deleteNative(c.getSource().getPlayerOrException());}catch(Exception e){c.getSource().sendFailure(net.minecraft.network.chat.Component.literal("删除失败："+e.getMessage()));return 0;}}))).then(Commands.literal("thinking").then(see).then(deep)).then(Commands.literal("default").executes(c->ServerChatSettings.menu(c.getSource().getPlayerOrException(),"default")).then(Commands.argument("agent",StringArgumentType.greedyString()).executes(c->ServerChatSettings.defaultReply(c.getSource().getPlayerOrException(),StringArgumentType.getString(c,"agent"))))).then(Commands.literal("cancel_send").then(Commands.argument("pending",net.minecraft.commands.arguments.UuidArgument.uuid()).executes(c->dev.mineagent.runtime.neoforge.ui.ServerConversations.get(c.getSource().getServer()).cancelQueued(c.getSource().getPlayerOrException(),net.minecraft.commands.arguments.UuidArgument.getUuid(c,"pending"))))));}
 private ChatPreferenceCommands(){}
}
